    Periodo = apps.get_model('capacitacion', 'Periodo')

    huerfanos = ContenidoBloqueRespuesta.objects.filter(inscripcion__isnull=True).select_related(
        'bloque__tema__modulo__curso',
    )
    for respuesta in huerfanos:
        curso = respuesta.bloque.tema.modulo.curso
        inscripcion = Inscripcion.objects.filter(colaborador_id=respuesta.colaborador_id, curso=curso).first()
        if inscripcion is None:
            periodo, _ = Periodo.objects.get_or_create(
                curso=curso,
                nombre='Periodo histórico (migración automática)',
                defaults={'fecha_inicio': timezone.now().date(), 'estado': 'cerrado'},
            )
            inscripcion = Inscripcion.objects.create(
                colaborador_id=respuesta.colaborador_id, curso=curso, periodo=periodo,
            )
        respuesta.inscripcion = inscripcion
        respuesta.save(update_fields=['inscripcion'])


